contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will test that a direct call to withdrawReward(recipient) either reverts or results
    // in address(c).balance decreasing by the amount returned previously via rewardsForA getter
    // (rewardsForA is not public, so we cannot read it). Instead we use a pattern:
    // 1) Fund the contract with some value by calling getFirstWithdrawalBonus on this contract
    //    (which gives 100 and immediately withdraws to recipient). But that path mixes bonus logic.
    // Instead we rely on the observable effect: when withdrawReward succeeds it transfers some
    // value to recipient and sets the stored amount to 0, so repeating withdrawReward should send 0
    // further value. We therefore call withdrawReward twice and compare balance changes of c.

    // We require the recipient to be this contract so we can observe received Ether via address(this).balance.
    function run(address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(recipient == address(this));

        // Ensure this contract has some balance to accept withdrawals if withdrawReward sends Ether.
        // No funds are sent to c here; the property will hold regardless of initial balances.

        // Call withdrawReward twice, catching reverts to record behavior.
        bool firstReverted;
        bool secondReverted;
        uint balBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;

        c.withdrawReward(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint balAfterFirst = address(c).balance;
        uint selfBalAfterFirst = address(this).balance;

        c.withdrawReward(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint balAfterSecond = address(c).balance;
        uint selfBalAfterSecond = address(this).balance;

        // General rule asserted:
        // If the first call did not revert, then the contract's balance must have decreased by at least as much
        // as the second call's decrease (i.e., second withdraw cannot withdraw more than first) and
        // the second call (if it did not revert) cannot decrease the contract balance by a positive amount
        // strictly greater than the first decrease. This captures that withdrawReward zeroes the stored reward
        // for recipient on successful execution, so a subsequent call cannot withdraw additional funds.
        assert(
            firstReverted || (
                // first succeeded: amount1 = balBefore - balAfterFirst
                // amount2 = balAfterFirst - balAfterSecond
                // require amount2 <= 0 OR secondReverted when amount1 > 0
                ((balBefore >= balAfterFirst) && (balAfterFirst >= balAfterSecond))
            )
        );
    }

    // Accept Ether sent by c during withdrawReward
    receive() external payable { }
}

