// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(address recipient) internal {
        vm.deal(address(c), VALUE_CAP);
        recipient = address(this);
        bool firstReverted;
        bool secondReverted;
        uint balBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;
        try c.withdrawReward(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint balAfterFirst = address(c).balance;
        uint selfBalAfterFirst = address(this).balance;
        try c.withdrawReward(recipient) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint balAfterSecond = address(c).balance;
        uint selfBalAfterSecond = address(this).balance;
        assertTrue(firstReverted || (
                // first succeeded: amount1 = balBefore - balAfterFirst
                // amount2 = balAfterFirst - balAfterSecond
                // require amount2 <= 0 OR secondReverted when amount1 > 0
                ((balBefore >= balAfterFirst) && (balAfterFirst >= balAfterSecond))
            ));
    }

    function testFuzz_run(address recipient) public {
        _run(recipient);
    }

    receive() external payable { }
}
